function mvpalab_cleansfdata(cfg)
%% MVPALAB_CLEANSFDATA
%
%  This function removes the filtered data generated by a previous import
%  of a sliding filter analysis, so the files of its bands and subjects do
%  not stay in cfg.sf.filesLocation next to those of the new import.
%
%  cfg.sf.filesLocation can be any folder selected by the user, so only
%  the files generated by the toolbox are removed: the feature vectors
%  (fv/s_*/ffv_*.mat) and the filtered data (data/s_*/fdata_*.mat). The
%  folders are removed only if they become empty.
%
%%  INPUT:
%
%  - {struct} - cfg:
%    Configuration structure (cfg.sf.filesLocation).

generated = {'fv','ffv_*.mat';'data','fdata_*.mat'};

for i = 1 : size(generated,1)
    folder = fullfile(cfg.sf.filesLocation,generated{i,1});

    files = dir(fullfile(folder,'s_*',generated{i,2}));
    for file = 1 : length(files)
        delete(fullfile(files(file).folder,files(file).name));
    end

    % rmdir fails without the 's' option if the folder is not empty:
    subjects = dir(fullfile(folder,'s_*'));
    for sub = 1 : length(subjects)
        [~,~] = rmdir(fullfile(subjects(sub).folder,subjects(sub).name));
    end
    [~,~] = rmdir(folder);
end

end
